const input = $input.first().json;
const body = input.body || {};
const token = String(body.token || '').trim();
const decision = body.decision === 'approved' || body.decision === 'changes_requested' ? body.decision : '';
const channel = body.channel === 'website' ? 'website' : 'email';
const changeNotes = body.changeNotes || '';
const decidedBy = body.decidedBy || '';

const missingFields = !token || !decision;

return [{ json: { token: token, decision: decision, channel: channel, changeNotes: changeNotes, decidedBy: decidedBy, missingFields: missingFields } }];

const orig = $('Normalize & Validate').first().json;
const rows = $input.all().map(function(item) { return item.json; });
const row = rows.find(function(r) { return r.token && r.token === orig.token; }) || null;

const notFound = !row;
const nowMs = Date.now();
const isExpired = !notFound && row.expires_at && new Date(row.expires_at).getTime() < nowMs && row.status === 'awaiting_approval';
const alreadyDecided = !notFound && !isExpired && row.status !== 'awaiting_approval';

return [{ json: {
  token: orig.token, decision: orig.decision, channel: orig.channel, changeNotes: orig.changeNotes, decidedBy: orig.decidedBy,
  notFound: notFound, isExpired: isExpired, alreadyDecided: alreadyDecided,
  row: row || {}
} }];

var input = $input.first().json;
var row = input.row;
var messages = {
  approved: 'This proposal was already approved on ' + row.decided_at + '. Your build is already underway.',
  changes_requested: 'Changes were already requested for this proposal on ' + row.decided_at + '. We will follow up directly.',
  expired: 'This proposal link has expired.'
};
return [{ json: { status: row.status, decidedAt: row.decided_at, channel: row.channel, message: messages[row.status] || ('This proposal is already marked ' + row.status + '.') } }];

